/* Reviewed English edition: phase4 */
(function () {
  'use strict';
  var translations = {"TRANG CHỦ": "HOME", "ỨNG DỤNG": "APPS", "Khám phá Apps": "Explore Apps", "TRÒ CHƠI": "GAMES", "Khu trò chơi": "Games Hub", "CÔNG CỤ": "TOOLS", "Khám phá Công cụ": "Explore Tools", "AI": "AI", "Khu AI": "AI Hub", "XỔ SỐ": "LOTTERY", "ĐI CHỢ": "SHOPPING", "TIN TỨC": "NEWS", "HỌC VIỆN MAY MẶC": "GARMENT ACADEMY", "THƯ VIỆN KIẾN THỨC DỆT MAY": "TEXTILE & APPAREL KNOWLEDGE LIBRARY", "Vật liệu & dệt": "Materials & Textiles", "Thiết kế & sản phẩm": "Design & Product Development", "Sản xuất": "Manufacturing", "Chất lượng": "Quality", "Quản trị & thương mại": "Business & Merchandising", "Từ điển": "Dictionary", "← Thư viện Garment Academy": "← Garment Academy Library", "Mỗi thứ một chút. Nhưng đều đáng dùng.": "A little of everything, chosen to be useful.", "BẮT ĐẦU": "GET STARTED", "Trang chủ": "Home", "Ứng dụng": "Apps", "Công cụ": "Tools", "Trò chơi": "Games", "HỌC VIỆN": "ACADEMY", "Garment Academy": "Garment Academy", "Từ điển Anh – Việt – Trung": "English–Vietnamese–Chinese Dictionary", "Chuỗi cung ứng & thương mại": "Supply Chain & Trade", "Chuyển đổi số & dữ liệu": "Digital Transformation & Data", "Chính sách bảo mật": "Privacy Policy", "Điều khoản sử dụng": "Terms of Use", "Liên hệ": "Contact", "Về AppNho": "About AppNho", "© 2026 AppNho · Garment Academy": "© 2026 AppNho · Garment Academy", "Thông số kỹ thuật cần đối chiếu với tech pack, tiêu chuẩn và yêu cầu đã duyệt của từng sản phẩm.": "Technical requirements must be checked against the approved tech pack, standards and product-specific requirements.", "Xơ dệt": "Textile Fibres", "Công nghệ sợi": "Yarn Technology", "Kiểm tra chất lượng": "Quality Inspection", "Nguồn": "References", "Dệt kim": "Knitting", "Vải không dệt": "Nonwoven Fabrics", "Tài liệu tham khảo": "References", "Tiền xử lý": "Pretreatment", "Nhuộm": "Dyeing", "In vải": "Textile Printing", "Hoàn tất": "Finishing", "QC & lỗi": "Quality Control & Defects", "Nguyên tắc kỹ thuật: không có một công thức nhiệt độ, pH, thời gian hay hóa chất dùng chung cho mọi mã vải. Quy trình phụ thuộc loại xơ, thuốc nhuộm, thiết bị, độ sâu màu, tỷ lệ liquor, tải máy, chất trợ và yêu cầu khách hàng. Các con số trong tài liệu tham khảo chỉ là ví dụ của một hệ công nghệ; phải dùng recipe đã được lab dip, pilot và nhà cung cấp hóa chất xác nhận.": "Technical principle: there is no single temperature, pH, time or chemical recipe that applies to every fabric style. The process depends on fibre type, dyes, equipment, shade depth, liquor ratio, machine load, auxiliaries and customer requirements. Figures in reference materials are examples for a particular process system; use a recipe confirmed through lab dips, a pilot trial and the chemical supplier.", "Cách học và áp dụng. Với mỗi cấu trúc, hãy nhận diện hướng sợi/vòng, bề mặt, cách liên kết và chỉ tiêu kiểm tra liên quan. Khi làm việc với một mã hàng, ghi rõ tiêu chuẩn thử, điều kiện điều hòa mẫu, vị trí lấy mẫu, đơn vị và phiên bản spec đang áp dụng để các kết quả có thể đối chiếu được.": "How to study and apply this material: for each construction, identify the yarn/loop direction, surface, bonding method and relevant inspection parameters. For each style, record the test standard, specimen-conditioning conditions, sampling location, unit and applicable specification revision so that results can be compared.", "Đọc thông số trước khi đọc tên thương mại. Tên “cotton”, “polyester” hay “viscose” chỉ cho biết một phần nguyên liệu. Cần xác nhận thành phần %, dạng staple/filament, độ mảnh, chiều dài xơ, cấu trúc sợi, count, twist, độ đều và yêu cầu sử dụng. Các giá trị thử nghiệm chỉ có ý nghĩa khi đi kèm đơn vị, phương pháp và điều kiện thử.": "Read the specification before relying on the commercial name. “Cotton”, “polyester” or “viscose” identifies only part of the raw material. Confirm the percentage composition, staple/filament form, fineness, fibre length, yarn structure, count, twist, evenness and end-use requirements. Test values are meaningful only when accompanied by units, methods and test conditions.", "🛠️ ỨNG DỤNG": "🛠️ APPS", "🎮 TRÒ CHƠI": "🎮 GAMES", "🧰 CÔNG CỤ": "🧰 TOOLS", "🎟️ XỔ SỐ": "🎟️ LOTTERY", "🛍️ ĐI CHỢ": "🛍️ SHOPPING", "📰 TIN TỨC": "📰 NEWS", "📚 HỌC VIỆN MAY MẶC": "📚 GARMENT ACADEMY", "GARMENT ACADEMY · THƯ VIỆN KIẾN THỨC": "GARMENT ACADEMY · KNOWLEDGE LIBRARY", "Mở menu": "Open menu", "Điều hướng AppNho": "AppNho navigation", "Điều hướng trong học viện": "Academy navigation", "Sáu nhóm kiến thức": "Six knowledge areas", "Mục lục chuyên đề": "Topic contents", "Phần A. Xơ dệt và tính chất nguyên liệu": "Part A. Textile Fibres and Raw-Material Properties", "Từ polymer/xơ đến sản phẩm vải": "From Polymer and Fibre to Fabric", "01 · Xơ, filament và staple: phân biệt ngay từ đầu": "01 · Fibre, Filament and Staple: Key Distinctions", "Fiber là đơn vị vật liệu có chiều dài lớn so với đường kính, đủ bền và linh hoạt để tạo cấu trúc dệt. Staple là xơ có chiều dài hữu hạn, ví dụ cotton tự nhiên hoặc polyester staple cắt đoạn; filament là sợi liên tục, ví dụ filament polyester/nylon hoặc tơ tằm. Staple thường phải qua kéo sợi để tạo yarn; filament có thể dùng trực tiếp hoặc ghép nhiều filament thành multifilament yarn. Filament cũng có thể được cắt thành staple để kéo sợi pha.": "A fibre is a material unit whose length is large relative to its diameter and which has sufficient strength and flexibility to form textile structures. Staple fibres have a finite length, such as natural cotton or cut polyester staple; filaments are continuous, such as polyester/nylon filaments or silk. Staple fibres generally undergo spinning to form yarn, while filaments can be used directly or combined into multifilament yarn. Filaments can also be cut into staple for blended spinning.", "Khi phát triển vật liệu, yêu cầu nhà cung cấp khai báo chiều dài staple hoặc số lượng/độ mảnh filament, tiết diện, độ bóng và trạng thái texturizing. Khi đổi từ spun sang filament cùng polymer, cần duyệt lại bề mặt, độ rủ, độ xù, độ bám màu và hành vi đường may trên mẫu may thử.": "During material development, ask the supplier to declare staple length or filament count/fineness, cross-section, lustre and texturing status. When changing from spun yarn to filament yarn made from the same polymer, reassess surface appearance, drape, hairiness, dye uptake and seam behaviour on a sewn trial sample.", "02 · Cotton: xơ cellulose tự nhiên": "02 · Cotton: A Natural Cellulosic Fibre", "Cotton là xơ cellulose từ hạt bông, thường có dạng dẹt xoắn tự nhiên khi quan sát dưới kính hiển vi. Xơ hút ẩm tương đối tốt, dễ nhuộm bằng thuốc nhuộm phù hợp cellulose và có cảm giác quen thuộc trong trang phục thường ngày. Chất lượng phụ thuộc chiều dài, độ mảnh, độ bền, độ trưởng thành, tạp chất và độ đồng đều. Cotton có thể co khi giặt, nhăn và có thể giảm bền khi ướt/khô tùy cấu trúc và xử lý; không nên xem cotton là một chất lượng đồng nhất.": "Cotton is a cellulosic fibre obtained from the cotton plant seed. Under a microscope, it commonly shows a naturally twisted, flattened form. It absorbs moisture relatively well, can be dyed with dyes suitable for cellulose and has a familiar hand in everyday apparel. Quality depends on length, fineness, strength, maturity, impurities and uniformity. Cotton may shrink during washing, crease and show different wet/dry strength behaviour depending on construction and treatment; cotton should not be treated as a single uniform quality.", "Trong cotton, chiều dài xơ và phân bố chiều dài ảnh hưởng khả năng kéo sợi và mức xơ ngắn; micronaire là chỉ số liên quan đến độ mảnh và độ trưởng thành, không nên diễn giải riêng lẻ như một chỉ tiêu chất lượng tổng hợp. Khi nhận hàng, liên kết bale/lot với kết quả HVI hoặc báo cáo nhà cung cấp và kiểm tra ảnh hưởng trên yarn pilot.": "For cotton, fibre length and length distribution affect spinnability and short-fibre content. Micronaire relates to fineness and maturity and should not be interpreted alone as an overall quality score. On receipt, link each bale/lot to its HVI results or supplier report and verify the effect in a yarn pilot.", "03 · Polyester: xơ tổng hợp phổ biến": "03 · Polyester: A Widely Used Synthetic Fibre", "Polyester may mặc thường là PET. Xơ có độ bền tốt, ít hút ẩm hơn cotton, khô nhanh và ổn định kích thước tương đối tốt khi được xử lý đúng. Polyester có thể sản xuất dạng staple hoặc filament, tròn hoặc tiết diện biến đổi, bóng hoặc mờ, texturized hoặc flat. Tính chất nhuộm, tích điện, pilling và cảm giác tay thay đổi theo cấu trúc xơ/sợi và hoàn tất.": "Apparel polyester is commonly PET. It has good strength, absorbs less moisture than cotton, dries quickly and can provide relatively good dimensional stability when processed correctly. Polyester is available as staple or filament, with round or modified cross-sections, bright or dull lustre, and textured or flat forms. Dyeing behaviour, static build-up, pilling and hand feel vary with fibre/yarn construction and finishing.", "Với polyester staple, phân biệt cut length, fineness, crimp và finish; với filament, ghi dtex/denier, filament count, cross-section và flat/textured. Khi ép nhiệt hoặc hoàn tất nhiệt, theo dõi thay đổi kích thước, bóng mặt, shade và recovery trên đúng tổ hợp vải–nhiệt–thời gian của quy trình.": "For polyester staple, distinguish cut length, fineness, crimp and finish. For filament, record dtex/denier, filament count, cross-section and whether it is flat or textured. During heat pressing or thermal finishing, monitor dimensional change, surface lustre, shade and recovery under the actual fabric–temperature–time combination used in the process.", "04 · Viscose, modal và lyocell: cellulose tái sinh": "04 · Viscose, Modal and Lyocell: Regenerated Cellulose", "Viscose, modal và lyocell là các nhóm xơ cellulose tái sinh, khác cotton tự nhiên về quá trình tạo xơ và cấu trúc. Chúng thường có khả năng hút ẩm và độ rủ tốt; viscose có thể giảm độ bền đáng kể khi ướt tùy loại, trong khi modal/lyocell được phát triển với các đặc tính cơ học và quy trình khác. Không gộp mọi rayon/cellulosic regenerated thành một loại có cùng hành vi.": "Viscose, modal and lyocell are groups of regenerated cellulosic fibres. Their fibre-forming processes and structures differ from natural cotton. They generally offer good moisture absorption and drape. Depending on the grade, viscose may lose substantial strength when wet, while modal and lyocell are developed with different mechanical properties and process characteristics. Do not treat all rayon or regenerated cellulosics as having identical behaviour.", "Khi dùng cellulose tái sinh, kiểm tra độ bền ướt theo đúng grade, co rút sau giặt, biến dạng khi ướt và hiện tượng fibrillation nếu là loại lyocell có xu hướng này. Với vải mỏng, đánh giá lực kéo khi trải, xô lớp và độ ổn định đường may trên mẫu trước khi chốt phương pháp cắt.": "When using regenerated cellulose, check wet strength for the specific grade, post-wash shrinkage, wet distortion and fibrillation where the lyocell type is susceptible. For lightweight fabrics, assess spreading tension, ply slippage and seam stability on a sample before finalising the cutting method.", "05 · Nylon/polyamide và elastane": "05 · Nylon/Polyamide and Elastane", "Nylon/polyamide thường có độ bền, khả năng chịu mài mòn và độ dai tốt, được dùng trong sportswear, lining, outerwear và sản phẩm kỹ thuật. Elastane/spandex là xơ đàn hồi cao, thường pha tỷ lệ nhỏ để tạo stretch và recovery; tên Lycra là nhãn hiệu, không phải tên chung của mọi elastane. Elastane nhạy với nhiệt, hóa chất và điều kiện xử lý nhất định; tỷ lệ pha không tự nói lên độ giãn thành phẩm.": "Nylon/polyamide generally offers good strength, abrasion resistance and toughness. It is used in sportswear, linings, outerwear and technical products. Elastane/spandex is a highly elastic fibre, usually blended in a small proportion to provide stretch and recovery. Lycra is a brand name, not the generic name for all elastane. Elastane is sensitive to certain temperatures, chemicals and processing conditions; blend percentage alone does not determine finished-garment stretch.", "Với elastane-covered yarn hoặc core-spun yarn, xác định elastane nằm trong lõi hay được quấn phủ, số lớp phủ, tỷ lệ và hướng xoắn. Khi đánh giá recovery, ghi chu kỳ kéo, mức kéo, thời gian nghỉ và nhiệt độ điều hòa; kết quả chỉ có ý nghĩa khi phương pháp được giữ nhất quán.": "For elastane-covered or core-spun yarn, identify whether elastane is in the core or used as a covering, the number of covering layers, blend ratio and twist direction. When assessing recovery, record the stretch cycle, extension level, recovery time and conditioning temperature. Results are meaningful only when the method is consistent.", "06 · Acrylic, wool, polypropylene và xơ chuyên dụng": "06 · Acrylic, Wool, Polypropylene and Speciality Fibres", "Acrylic thường được dùng làm vật liệu thay thế/pha len với cảm giác ấm và nhẹ; wool là xơ protein có vảy bề mặt, độ đàn hồi và khả năng giữ ấm; polypropylene nhẹ và hút ẩm rất thấp, được dùng trong một số lớp chức năng/nonwoven. Aramid, glass, carbon và các xơ kỹ thuật có ứng dụng chuyên biệt, không nên xử lý như xơ may mặc phổ thông.": "Acrylic is often used as a lightweight, warm alternative to or blend with wool. Wool is a protein fibre with surface scales, natural resilience and thermal insulation. Polypropylene is lightweight and has very low moisture absorption; it is used in some functional layers and nonwovens. Aramid, glass, carbon and other technical fibres have specialised applications and should not be treated as ordinary apparel fibres.", "Wool cần quan tâm micron, staple length, crimp, scales và felting behavior; polypropylene cần xem độ bền nhiệt, khả năng nhuộm/hoàn tất và lão hóa theo ứng dụng. Với aramid, glass hoặc carbon, datasheet phải nêu rõ grade, dạng xơ, xử lý bề mặt và công đoạn gia công tương thích.": "For wool, consider micron, staple length, crimp, scales and felting behaviour. For polypropylene, assess thermal resistance, dyeing/finishing options and application-related ageing. For aramid, glass or carbon, the datasheet should specify grade, fibre form, surface treatment and compatible processing operations.", "07 · Blend và phối trộn: vì sao pha xơ?": "07 · Blends: Why Combine Fibres?", "Blend là phối hai hay nhiều loại xơ trong cùng sợi/vải để cân bằng giá, cảm giác, độ bền, hút ẩm, nhăn, khô nhanh, co rút hoặc hiệu năng. Ví dụ cotton/polyester có thể cải thiện độ ổn định và tốc độ khô so với cotton thuần, nhưng kết quả phụ thuộc tỷ lệ, cấu trúc và hoàn tất. Pha elastane có thể tăng co giãn; pha viscose có thể thay đổi độ rủ và cảm giác. Không có tỷ lệ pha tối ưu cho mọi sản phẩm.": "A blend combines two or more fibre types in the same yarn or fabric to balance cost, hand feel, strength, moisture absorption, creasing, drying rate, shrinkage or performance. For example, a cotton/polyester blend may improve dimensional stability and drying rate compared with pure cotton, but the result depends on blend ratio, construction and finishing. Elastane can increase stretch, while viscose can change drape and hand feel. There is no optimum blend ratio for every product.", "Khi kiểm soát blend, lấy mẫu ở nhiều package/điểm của lô và xác định phương pháp phân tích có khả năng phân biệt các thành phần. Với blend nhuộm hai thành phần, xây dựng shade approval cho từng thành phần và đánh giá metamerism dưới các nguồn sáng khách hàng yêu cầu.": "For blend control, sample multiple packages/locations within the lot and select an analytical method capable of distinguishing the components. For blends dyed with two colourant systems, establish shade approval for each fibre component and assess metamerism under the light sources required by the customer.", "08 · Các tính chất xơ cần đọc trên datasheet": "08 · Fibre Properties to Review in a Datasheet", "Các tính chất thường gặp gồm chiều dài staple, độ mảnh/fineness, độ bền, elongation, modulus, moisture regain, crimp, friction, maturity và độ đồng đều. Fineness ảnh hưởng số xơ trong tiết diện sợi; staple length và độ đồng đều ảnh hưởng khả năng kéo sợi; strength/elongation ảnh hưởng chịu lực; moisture behavior ảnh hưởng xử lý và thoải mái. Một tính chất đơn lẻ không quyết định chất lượng tổng thể.": "Common properties include staple length, fineness, strength, elongation, modulus, moisture regain, crimp, friction, maturity and uniformity. Fineness affects the number of fibres in a yarn cross-section; staple length and uniformity affect spinnability; strength and elongation affect load-bearing behaviour; moisture behaviour affects processing and comfort. No single property determines overall quality.", "Đọc datasheet theo chuỗi: tên phương pháp → đơn vị → điều kiện thử → giá trị trung bình → biến thiên/phân bố → giới hạn hợp đồng. Nếu nhà cung cấp chỉ đưa một giá trị trung bình, yêu cầu dữ liệu phân bố hoặc kết quả theo lot khi biến thiên nguyên liệu có thể ảnh hưởng đến chất lượng vải.": "Read a datasheet in sequence: method name → unit → test conditions → average value → variation/distribution → contractual limit. If the supplier provides only an average, request distribution data or lot-specific results when raw-material variation could affect fabric quality.", "09 · Nhận diện xơ: không chỉ dựa vào cảm giác hoặc đốt": "09 · Fibre Identification: Beyond Touch or Burn Tests", "Nhận diện có thể dựa trên nhãn/traceability, kính hiển vi, hòa tan hóa học, phân tích nhiệt hoặc phổ hồng ngoại tùy yêu cầu. Thử đốt chỉ cho dấu hiệu sơ bộ; xơ pha và vật liệu hoàn tất có thể làm kết quả khó diễn giải. Khi cần kết luận thành phần, chọn phương pháp phân tích phù hợp như kính hiển vi, hòa tan chọn lọc hoặc phổ hồng ngoại và lưu báo cáo cùng mẫu đối chứng.": "Identification may rely on labels/traceability, microscopy, chemical dissolution, thermal analysis or infrared spectroscopy, depending on the requirement. A burn test provides only preliminary indications; blends and finished materials can make the results difficult to interpret. When a definitive composition is required, select an appropriate analytical method such as microscopy, selective dissolution or infrared spectroscopy, and retain the report with a reference specimen.", "Trong báo cáo nhận diện, ghi mẫu nhận được, tình trạng nguyên trạng hay đã nhuộm/hoàn tất, phương pháp phân tích, giới hạn phát hiện và cách diễn giải blend. Với mẫu tranh chấp, niêm phong mẫu, chụp ảnh, ghi người bàn giao/nhận và giữ mẫu lưu để tái kiểm tra.": "An identification report should record the received specimen, whether it is untreated or dyed/finished, the analytical method, detection limits and interpretation of any blend. For disputed samples, seal the specimen, take photographs, record the handover parties and retain a reference sample for re-testing.", "10 · Lựa chọn xơ theo sản phẩm cuối": "10 · Selecting Fibres for the End Product", "Áo sơ mi cần cân nhắc cảm giác, nhăn, độ thoáng và chăm sóc; sportswear cần stretch/recovery, moisture management, abrasion và độ bền màu; jacket cần độ ổn định, lớp phủ/lót và khả năng chịu môi trường; đồ trẻ em cần xem xét yêu cầu an toàn, hóa chất và nhãn theo thị trường. Tên xơ không thể thay cho đặc tính vải hoàn thiện.": "Shirting requires consideration of hand feel, creasing, breathability and care. Sportswear requires stretch/recovery, moisture management, abrasion resistance and colourfastness. Jackets require stability, suitable coatings/linings and environmental resistance. Children's garments require attention to safety, chemical and labelling requirements in the target market. Fibre names cannot substitute for the properties of the finished fabric.", "Ma trận lựa chọn nên có cột end-use, yêu cầu cảm giác, cơ lý, chăm sóc, môi trường sử dụng, khả năng sản xuất, chi phí và phép thử xác nhận. Chốt nguyên liệu sau khi đánh giá cả vải thành phẩm và sản phẩm may thử; không quyết định chỉ dựa trên bảng tính chất xơ thô.": "A selection matrix should include end use, hand-feel requirements, mechanical properties, care, use environment, manufacturability, cost and verification tests. Finalise the material only after evaluating both the finished fabric and a sewn product trial; do not decide from a raw-fibre property table alone.", "Phần B. Công nghệ sợi và cấu trúc yarn": "Part B. Yarn Technology and Yarn Structure", "01 · Kiểm tra đầu vào theo lô": "01 · Incoming Inspection by Lot", "Một kết quả thử chỉ đại diện cho mẫu đã lấy, không tự động đại diện toàn bộ lô. Kế hoạch lấy mẫu cần xác định số package/lot, vị trí lấy mẫu, lượng mẫu và tiêu chí chấp nhận theo hợp đồng. Với yarn package, cần xem biến thiên giữa package chứ không chỉ trung bình lô; một vài package khác biệt có thể tạo sọc hoặc barré trong cùng cây vải.": "A test result represents only the specimen tested; it does not automatically represent the entire lot. The sampling plan should define the number of packages per lot, sampling locations, sample quantity and contractual acceptance criteria. For yarn packages, assess package-to-package variation rather than relying only on the lot average. A few outlying packages can create streaks or barré within the same fabric roll.", "Kế hoạch lấy mẫu cần có quy tắc chọn package ngẫu nhiên, cách lấy mẫu đầu/cuối package khi cần, mã hóa mẫu và cách xử lý package bị loại. Khi phát hiện outlier, kiểm tra xem đó là khác biệt package, vị trí lấy mẫu hay sai số thiết bị trước khi mở rộng phạm vi cách ly.": "The sampling plan should define random package selection, how to sample the beginning/end of a package where required, sample identification and handling of rejected packages. When an outlier is found, determine whether it is due to package variation, sampling location or equipment error before expanding the containment scope.", "02 · Điều hòa mẫu và phương pháp thử": "02 · Specimen Conditioning and Test Methods", "Độ ẩm và nhiệt độ ảnh hưởng khối lượng, điện dung và một số phép đo cơ lý. Mẫu cần được điều hòa theo phương pháp thử quy định; báo cáo cần ghi tiêu chuẩn, thiết bị, setting, số phép đo và điều kiện môi trường. Không so hai báo cáo chỉ vì cùng tên chỉ tiêu nếu phương pháp khác nhau.": "Moisture and temperature affect mass, capacitance and some mechanical measurements. Specimens must be conditioned according to the specified test method. Reports should state the standard, equipment, settings, number of measurements and environmental conditions. Two reports should not be compared merely because they use the same property name if their methods differ.", "Phiếu thử nên ghi tiêu chuẩn và phiên bản, phòng thử nghiệm, thiết bị, ngày hiệu chuẩn, nhiệt độ/độ ẩm, thời gian điều hòa, test speed, gauge length và số lần thử. Khi so hai report, đối chiếu từng trường này trước khi dùng kết quả làm căn cứ khiếu nại.": "The test record should state the standard and edition, laboratory, equipment, calibration date, temperature/humidity, conditioning time, test speed, gauge length and number of tests. When comparing two reports, check each of these fields before using the results as evidence in a claim.", "03 · Từ lỗi sợi đến lỗi vải": "03 · From Yarn Defects to Fabric Defects", "Yarn count variation, hairiness, twist variation, contamination và imperfections có thể biểu hiện thành barré, streak, cloudiness, uneven texture, end break hoặc needle damage. Tuy nhiên, lỗi vải cũng có thể phát sinh ở máy dệt/đan, nhuộm hoặc hoàn tất. Cần truy dấu theo hướng lỗi, tính lặp, package và machine position.": "Yarn count variation, hairiness, twist variation, contamination and yarn imperfections may appear as barré, streaks, cloudiness, uneven texture, end breaks or needle damage. However, fabric defects may also originate in weaving/knitting, dyeing or finishing. Trace the issue using defect direction, repetition, package identity and machine position.", "Đối chiếu vị trí lỗi trên fabric với package map, creel position, spindle/rotor position và log thay package. Nếu lỗi lặp theo chu kỳ hoặc vị trí máy, khoanh vùng nguồn cấp tương ứng; nếu xuất hiện rải rác theo lot, so sánh phân bố count, twist, hairiness và contamination giữa package.": "Compare fabric defect locations with the package map, creel position, spindle/rotor position and package-change log. If defects repeat by machine cycle or position, isolate the corresponding feed source. If they occur sporadically across a lot, compare count, twist, hairiness and contamination distributions between packages.", "04 · Ví dụ đọc count và biến thiên": "04 · Example: Reading Yarn Count and Variation", "Giả sử phiếu ghi 30 tex, CVm 1,2%, hairiness H 5,0. 30 tex mô tả linear density danh nghĩa; CVm mô tả mức biến thiên khối lượng theo phương pháp thiết bị; H là chỉ số hairiness theo phương pháp tương ứng. Ba số trả lời ba câu hỏi khác nhau. Không thể nói yarn “đạt” nếu chưa có spec giới hạn và method.": "Assume a report states 30 tex, CVm 1.2% and hairiness H 5.0. The 30 tex value describes nominal linear density; CVm describes mass variation under the instrument method; H is a hairiness index under the corresponding method. These three values answer different questions. The yarn cannot be declared compliant without specification limits and the applicable test methods.", "Khi đọc CVm, U%, H, S3 hoặc imperfections, phải giữ đúng tên chỉ số và cấu hình thiết bị. Không quy đổi hoặc so trực tiếp giữa các chỉ số khác định nghĩa; tạo bảng trend theo lot và package để phát hiện drift trước khi ảnh hưởng thành vải.": "When reading CVm, U%, H, S3 or imperfection results, retain the exact index name and instrument configuration. Do not convert or directly compare indices with different definitions. Build lot- and package-level trend charts to detect drift before it affects fabric quality.", "05 · Quy trình xử lý khi yarn lot có vấn đề": "05 · Handling a Problematic Yarn Lot", "Khi phát hiện lỗi, cô lập lot nghi ngờ, dừng cấp vào sản xuất nếu rủi ro ảnh hưởng lớn, xác định phạm vi cuộn/package liên quan, lấy mẫu xác nhận và thông báo supplier. So sánh với retained sample và lô trước; kiểm tra sản phẩm đã sản xuất để xác định mức ảnh hưởng. Quyết định rework, downgrade hay reject phải theo quyền phê duyệt và yêu cầu khách hàng.": "When a defect is detected, quarantine the suspected lot and stop issuing it to production if the risk is significant. Identify the affected rolls/packages, take confirmation samples and notify the supplier. Compare the results with retained samples and previous lots, and inspect products already manufactured to determine the extent of impact. Rework, downgrade or rejection decisions must follow the authorised approval process and customer requirements.", "Hồ sơ xử lý nên có mã NCR, mô tả lỗi, lot/package bị ảnh hưởng, số lượng đã cấp chuyền, WIP/thành phẩm liên quan, hành động containment, kết quả xác minh nguyên nhân, disposition và bằng chứng hiệu lực sau khắc phục. Chỉ đóng NCR khi có người chịu trách nhiệm xác nhận kết quả.": "The disposition record should include the NCR number, defect description, affected lot/packages, quantity issued to the line, related WIP/finished goods, containment actions, verified root cause, disposition and evidence of corrective-action effectiveness. Close the NCR only after the responsible person has confirmed the result.", "Phòng thực hành kéo sợi và đọc yarn specification": "Workshop: Spinning Processes and Yarn Specification Review", "Phần này nối kiến thức xơ với quyết định chọn yarn cho vải. Các sơ đồ là luồng công nghệ giản lược; bố trí thực tế có thể khác theo nhà máy, nguyên liệu, hệ kéo sợi và mức tích hợp thiết bị.": "This section connects fibre knowledge with yarn selection for fabric production. The diagrams show simplified process flows; actual layouts vary by factory, raw material, spinning system and level of equipment integration.", "1. Quy trình kéo sợi từ xơ staple": "1. Staple-Fibre Spinning Process", "*Roving thường có trong quy trình ring spinning; rotor và một số hệ kéo sợi khác có đường công nghệ khác, không nhất thiết dùng roving frame.": "*Roving is commonly used in ring spinning. Rotor and some other spinning systems follow different process routes and do not necessarily use a roving frame.", "Mở kiện, tách xơ và phối trộn để tạo nguồn cấp tương đối đồng đều. Cần kiểm soát lot, tỷ lệ blend và nhiễm bẩn chéo.": "Bales are opened, fibres separated and blended to create a reasonably uniform feed. Control the lot, blend ratio and cross-contamination.", "Làm sạch, tách xơ, loại một phần tạp và tạo sliver. Carding ảnh hưởng độ song song và độ đồng đều của dòng xơ.": "Fibres are opened and cleaned, some impurities are removed, and a sliver is formed. Carding affects fibre parallelisation and the uniformity of the fibre stream.", "Ghép và kéo dài nhiều sliver để cải thiện độ đều, trộn xơ và định hướng xơ hơn. Số passage tùy hệ thống và yêu cầu.": "Multiple slivers are combined and drafted to improve evenness, blend fibres and further align them. The number of passages depends on the system and requirements.", "Roving tạo sợi thô có độ xoắn nhẹ để cấp cho ring frame. Spinning kéo mảnh và tạo độ xoắn/bonding cần thiết để yarn có độ bền.": "Roving produces a lightly twisted intermediate strand for feeding to the ring frame. Spinning drafts the strand and inserts the twist needed to give the yarn strength.", "Cuốn yarn thành package phù hợp công đoạn sau; có thể làm sạch lỗi theo setting và nối đầu sợi. Không được mặc định mọi clearer setting giống nhau.": "The yarn is wound into a package suitable for the next process. Defects may be cleared and yarn ends joined according to the settings. Clearer settings must not be assumed to be identical for all yarns.", "Kiểm tra count, evenness, imperfections, hairiness, strength, elongation, twist và package condition theo spec.": "Inspect count, evenness, imperfections, hairiness, strength, elongation, twist and package condition against the specification.", "2. Filament spinning: từ polymer đến filament yarn": "2. Filament Spinning: From Polymer to Filament Yarn", "Với melt spinning, polymer được làm nóng chảy, đùn qua spinneret thành các filament, làm nguội/đông đặc, kéo giãn để định hướng phân tử và cuốn thành package. Một số polymer cần điều kiện sấy và kiểm soát độ ẩm trước khi đùn. Các hệ wet spinning hoặc dry spinning có cơ chế tạo filament khác, thường dùng dung dịch polymer và bước loại dung môi/đông tụ phù hợp.": "In melt spinning, polymer is melted and extruded through a spinneret to form filaments. The filaments are quenched/solidified, drawn to orient the molecules and wound into packages. Some polymers require controlled drying and moisture before extrusion. Wet-spinning and dry-spinning systems form filaments differently, generally using polymer solutions followed by suitable solvent removal or coagulation.", "3. Ring, rotor và air-jet spinning": "3. Ring, Rotor and Air-Jet Spinning", "Hệ kéo sợi": "Spinning system", "Nguyên lý khái quát": "General principle", "Đặc điểm yarn thường gặp": "Typical yarn characteristics", "Điểm cần xem khi lựa chọn": "Selection considerations", "Ring spinning": "Ring spinning", "Roving được kéo mảnh; spindle và traveller tạo twist, cuốn yarn lên bobbin": "Roving is drafted; the spindle and traveller insert twist and wind yarn onto a bobbin", "Yarn thường có cấu trúc tương đối đồng đều theo hệ; có thể tạo nhiều count và blend": "Yarn generally has a compact structure for the system; a wide range of counts and blends can be produced", "Strength, hairiness, evenness, twist, count, productivity và chi phí công đoạn": "Strength, hairiness, evenness, twist, count, productivity and process cost", "Rotor / open-end": "Rotor / open-end", "Xơ từ sliver được mở riêng lẻ, đưa vào rotor groove và gom thành yarn có twist": "Fibres from a sliver are separated, fed into the rotor groove and collected into a twisted yarn", "Cấu trúc và phân bố xơ khác ring; thường phù hợp một số count/ứng dụng nhất định": "Fibre arrangement differs from ring yarn; the system is suited to selected counts and applications", "Count range, strength, handle, evenness, end use, năng suất và giới hạn nguyên liệu": "Count range, strength, hand, evenness, end use, productivity and raw-material limitations", "Air-jet spinning": "Air-jet spinning", "Dòng khí xoáy tạo cấu trúc yarn với phần xơ quấn/bọc quanh lõi xơ gần song song": "Air vortices form a yarn in which wrapper fibres surround a largely parallel fibre core", "Yarn có cấu trúc khác ring/rotor; hairiness và handle có thể khác theo loại máy, nguyên liệu và setting": "The yarn structure differs from ring and rotor yarn; hairiness and hand vary with machine type, raw material and settings", "Fiber length/fineness, blend, strength, pilling, hairiness, count range và tính phù hợp vải": "Fibre length/fineness, blend, strength, pilling, hairiness, count range and fabric suitability", "Bảng so sánh định tính. Không thể kết luận hệ nào “tốt nhất” nếu chưa biết loại xơ, count, cấu trúc vải, yêu cầu ngoại quan, cơ lý và năng lực thiết bị cụ thể.": "This is a qualitative comparison. No spinning system can be identified as “best” without knowing the fibre type, count, fabric construction, appearance and mechanical requirements, and the specific equipment capability.", "4. Hệ đo chi số sợi: direct và indirect count": "4. Yarn Count Systems: Direct and Indirect", "Linear density mô tả khối lượng trên một chiều dài xác định. Tex, dtex và denier là hệ trực tiếp: số càng lớn thì sợi càng nặng trên cùng chiều dài. Ne và Nm là hệ gián tiếp: số càng lớn thì sợi càng mảnh trong cùng hệ quy ước.": "Linear density describes mass per defined length. Tex, dtex and denier are direct systems: a higher number means a heavier yarn over the same length. Ne and Nm are indirect systems: a higher number means a finer yarn within the same counting convention.", "Hệ": "System", "Định nghĩa": "Definition", "Quan hệ với tex": "Relationship to tex", "Ghi chú": "Notes", "Gram trên 1.000 m": "Grams per 1,000 m", "tex = g × 1.000 / m": "tex = g × 1,000 / m", "Hệ trực tiếp": "Direct system", "Gram trên 10.000 m": "Grams per 10,000 m", "dtex = 10 × tex": "dtex = 10 × tex", "Gram trên 9.000 m": "Grams per 9,000 m", "den = 9 × tex": "den = 9 × tex", "Số km trên 1 kg": "Kilometres per kilogram", "Nm = 1.000 / tex": "Nm = 1,000 / tex", "Hệ gián tiếp theo hệ mét": "Indirect metric system", "Số hank 840 yard trên 1 pound": "Number of 840-yard hanks per pound", "Ne ≈ 590,5 / tex": "Ne ≈ 590.5 / tex", "Hệ cotton count; phải ghi rõ quy ước": "Cotton count system; state the convention used", "5. Đọc chỉ tiêu độ đồng đều và lỗi sợi": "5. Reading Yarn Evenness and Imperfection Results", "Khi đọc báo cáo evenness, cần phân biệt U% và CVm% theo cách tính của thiết bị. Hai chỉ số mô tả mức biến thiên khối lượng theo chiều dài nhưng không nên thay thế lẫn nhau nếu báo cáo, phương pháp hoặc cấu hình đo khác nhau. Bên cạnh chỉ số tổng hợp, cần xem các điểm mỏng (thin places), điểm dày (thick places), neps và hairiness theo ngưỡng mà đơn hàng hoặc tiêu chuẩn nội bộ quy định.": "When reading an evenness report, distinguish U% from CVm% according to the instrument's calculation method. Both describe mass variation along the yarn, but they should not be used interchangeably when the report, method or instrument configuration differs. In addition to summary indices, review thin places, thick places, neps and hairiness against the thresholds specified by the order or internal standard.", "Chỉ tiêu": "Parameter", "Ý nghĩa khi đọc báo cáo": "Meaning in the report", "Câu hỏi kiểm tra": "Verification question", "U% / CVm%": "U% / CVm%", "Mức không đều khối lượng theo chiều dài sợi": "Mass irregularity along the yarn length", "Đang dùng chỉ số nào, thiết bị nào, chiều dài và tốc độ đo bao nhiêu?": "Which index and instrument are used, and what are the test length and speed?", "Thin places": "Thin places", "Đoạn sợi mảnh hơn ngưỡng cài đặt": "Yarn sections thinner than the set threshold", "Ngưỡng tính theo phần trăm độ mảnh và số lỗi trên chiều dài nào?": "What percentage-thickness threshold is used, and how many faults are counted over what length?", "Thick places": "Thick places", "Đoạn sợi dày hơn ngưỡng cài đặt": "Yarn sections thicker than the set threshold", "Ngưỡng và độ nhạy của thiết bị có giống báo cáo đối chiếu?": "Are the threshold and instrument sensitivity the same as in the comparison report?", "Neps": "Neps", "Các điểm kết tụ xơ hoặc nút nhỏ được thiết bị nhận diện theo thuật toán": "Fibre entanglements or small knots identified by the instrument algorithm", "Ngưỡng kích thước/độ dày và cách phân loại neps được ghi rõ chưa?": "Are the size/thickness threshold and nep classification method clearly stated?", "Hairiness": "Hairiness", "Mức xơ/sợi nhô khỏi thân sợi theo chỉ số của thiết bị": "The amount of fibre/yarn protruding from the yarn body, as measured by the instrument index", "Chỉ số H hoặc phương pháp đo nào đang được dùng?": "Which H index or measurement method is being used?", "6. Đọc yarn datasheet: ví dụ mô phỏng": "6. Reading a Yarn Datasheet: Illustrative Example", "Trường thông tin": "Field", "Ví dụ mô phỏng": "Illustrative example", "Câu hỏi cần đặt ra": "Questions to ask", "Composition": "Composition", "100% polyester staple spun": "100% polyester staple spun", "Polymer nào? Staple hay filament? Có recycled content claim không và bằng chứng gì?": "Which polymer? Staple or filament? Is recycled content claimed, and what evidence supports the claim?", "Count": "Count", "30 tex (nominal)": "30 tex (nominal)", "Đo theo phương pháp nào? Tolerance count bao nhiêu? Là single hay ply yarn?": "Which test method is used? What is the count tolerance? Is it a single or ply yarn?", "Twist": "Twist", "700 turns/m, S": "700 turns/m, S", "Twist direction S/Z? Twist measured hay nominal? Có yêu cầu sau conditioning?": "Is the twist direction S or Z? Is the twist measured or nominal? Are post-conditioning requirements specified?", "Evenness": "Evenness", "CVm 1,2% (ví dụ)": "CVm 1.2% (illustrative)", "Thiết bị, test length, speed và setting nào? CVm hay U%?": "Which instrument, test length, speed and settings are used? Is the index CVm or U%?", "H = 5,0 (ví dụ)": "H = 5.0 (illustrative)", "Chỉ số H của thiết bị/phương pháp nào? Có thể so sánh với report khác không?": "Which instrument/method defines H? Can it be compared with another report?", "Strength": "Strength", "Giá trị phải lấy từ report nhà cung cấp": "Value to be taken from the supplier's report", "Đơn vị cN/tex hay cN? Tenacity hay breaking force? Số phép đo?": "Is the unit cN/tex or cN? Is it tenacity or breaking force? How many tests were performed?", "Package": "Package", "Package ID / net weight / winding": "Package ID / net weight / winding", "Lot traceability, density, unwinding behavior và lỗi package?": "Lot traceability, package density, unwinding behaviour and package defects?", "Các con số count, twist, CVm và hairiness ở bảng là ví dụ minh họa cách đọc trường dữ liệu, không phải giới hạn chất lượng hay thông số mua hàng.": "The count, twist, CVm and hairiness values in this table illustrate how to read data fields. They are not quality limits or purchasing specifications.", "7. Chọn yarn theo mục đích vải": "7. Selecting Yarn for the Fabric End Use", "Mục đích": "End use", "Thuộc tính cần xác định": "Properties to define", "Rủi ro nếu chỉ chọn theo count": "Risk of selecting by count alone", "Áo thun jersey": "Jersey T-shirt", "Fiber blend, yarn construction, count, evenness, hairiness, strength, pilling và dyeability": "Fibre blend, yarn construction, count, evenness, hairiness, strength, pilling and dyeability", "Hai yarn cùng count có thể khác hairiness, bề mặt, độ bền và barré": "Two yarns with the same count may differ in hairiness, surface appearance, strength and barré", "Vải sơ mi woven": "Woven shirting", "Count, twist, ply, strength, evenness, hairiness, màu và khả năng chịu hồ/dệt": "Count, twist, ply, strength, evenness, hairiness, colour and sizing/weaving performance", "Count đúng nhưng twist hoặc evenness không phù hợp có thể ảnh hưởng ngoại quan và đứt sợi": "A correct count with unsuitable twist or evenness can affect appearance and cause yarn breaks", "Sportswear stretch": "Stretch sportswear", "Filament type, dtex/denier, elastane content, texturing, recovery và heat behavior": "Filament type, dtex/denier, elastane content, texturing, recovery and heat behaviour", "Chỉ biết denier không nói lên stretch/recovery hoặc độ ổn định nhiệt": "Denier alone does not describe stretch/recovery or thermal stability", "Vải chải lông / fleece": "Brushed fabric / fleece", "Staple quality, yarn strength, hairiness, blend và khả năng chịu xử lý cơ học": "Staple quality, yarn strength, hairiness, blend and resistance to mechanical processing", "Yarn có thông số danh nghĩa đạt nhưng có thể phát sinh shedding/pilling sau hoàn tất": "Yarn may meet nominal specifications yet develop shedding or pilling after finishing", "Woolmark Learning Centre, Assessing Yarn Evenness: .": "Woolmark Learning Centre, Assessing Yarn Evenness.", "Các tài liệu là nguồn học tập và giải thích thuật ngữ. Giới hạn chấp nhận cần theo yarn specification, tiêu chuẩn thử được viện dẫn và mục đích sử dụng.": "These materials are provided for learning and terminology reference. Acceptance limits must follow the yarn specification, cited test standard and intended end use.", "tex": "tex", "dtex": "dtex", "denier (den)": "denier (den)", "Nm": "Nm", "Ne (cotton count)": "Ne (cotton count)", "Xơ dệt, sợi và đặc tính nguyên liệu": "Textile Fibres, Yarns and Raw-Material Properties", "Từ cấu trúc xơ đến sợi thành phẩm: nhận diện cotton, polyester, viscose, nylon, elastane; hiểu staple và filament, yarn count, twist, evenness, hairiness, độ bền và cách lựa chọn sợi cho vải may mặc.": "From fibre structure to finished yarn: identify cotton, polyester, viscose, nylon and elastane; understand staple and filament, yarn count, twist, evenness, hairiness, strength and how to select yarn for apparel fabrics.", "Đọc thông số trước khi đọc tên thương mại.": "Read the Specification Before the Commercial Name", "Tên “cotton”, “polyester” hay “viscose” chỉ cho biết một phần nguyên liệu. Cần xác nhận thành phần %, dạng staple/filament, độ mảnh, chiều dài xơ, cấu trúc sợi, count, twist, độ đều và yêu cầu sử dụng. Các giá trị thử nghiệm chỉ có ý nghĩa khi đi kèm đơn vị, phương pháp và điều kiện thử.": "The names “cotton”, “polyester” and “viscose” identify only part of the raw material. Confirm percentage composition, staple/filament form, fineness, fibre length, yarn construction, count, twist, evenness and end-use requirements. Test values are meaningful only when accompanied by units, methods and test conditions.", "Ứng dụng trong nhà máy": "Factory Application", "Khi đọc spec, ghi rõ 100% polyester spun hay 100% polyester filament. Hai cấu trúc cùng polymer nhưng bề mặt, độ rủ, độ xù, độ bền và cách nhuộm có thể khác nhau.": "When reading a specification, state whether the material is 100% spun polyester or 100% polyester filament. Although both use the same polymer, their surface, drape, hairiness, strength and dyeing behaviour may differ.", "Với cotton yarn, kiểm tra fiber length, micronaire/fineness, strength, trash và count. Với thành phẩm, xác nhận shrinkage, skew/spirality, colorfastness và hướng dẫn chăm sóc theo đúng kết cấu vải.": "For cotton yarn, check fibre length, micronaire/fineness, strength, trash and count. For the finished fabric, confirm shrinkage, skew/spirality, colourfastness and care instructions for the actual construction.", "Không suy ra hiệu năng chỉ từ nhãn 100% polyester. Xác nhận spun/filament, DTEX/denier, texturing, cross-section, luster, heat setting và yêu cầu nhiệt khi ép/in. Tránh nhiệt quá mức vì có thể gây bóng, biến dạng hoặc co.": "Do not infer performance from a “100% polyester” label alone. Confirm spun/filament form, dtex/denier, texturing, cross-section, lustre, heat setting and the thermal requirements for pressing/printing. Excessive heat may cause glazing, distortion or shrinkage.", "Khi cắt may, kiểm tra shrinkage, wet strength, seam slippage, độ rủ và biến dạng sau giặt. Vải viscose mỏng có thể dễ xô lệch khi trải; cần đánh giá relax, chiều trải và cách giữ lớp.": "During cutting and sewing, check shrinkage, wet strength, seam slippage, drape and post-wash distortion. Lightweight viscose fabric may shift during spreading; assess relaxation, spreading direction and ply control.", "Đọc rõ tỷ lệ elastane và hướng stretch. Kiểm tra heat setting, nhiệt ép, chlorine/chemical exposure nếu liên quan, growth/recovery và độ bền đường may. Đừng dùng nhiệt bàn ủi như với cotton nếu chưa xác nhận nhãn chăm sóc.": "Read the elastane percentage and stretch direction carefully. Check heat setting, pressing temperature, chlorine/chemical exposure where relevant, growth/recovery and seam strength. Do not use cotton ironing temperatures unless confirmed by the care label.", "Với xơ chuyên dụng, yêu cầu datasheet và hướng dẫn an toàn/hoàn tất từ nhà cung cấp. Với sản phẩm có yêu cầu chống cháy, chống cắt hoặc bảo hộ, đối chiếu đúng mã vật liệu, cấu trúc thành phẩm, phương pháp thử và hồ sơ chứng nhận của lô cung ứng.": "For speciality fibres, request the supplier's datasheet and safety/finishing instructions. For products requiring flame, cut or other protection, verify the exact material code, finished construction, test method and certification records for the supplied lot.", "Kiểm tra thành phần bằng chứng từ nhà cung cấp hoặc phép thử nhận diện/thành phần khi cần. Với blend, đánh giá shrinkage và dyeing compatibility vì hai loại xơ có thể phản ứng khác nhau với thuốc nhuộm và nhiệt.": "Verify composition using supplier evidence or an identification/composition test where necessary. For blends, assess shrinkage and dyeing compatibility because the fibre components may respond differently to dyes and heat.", "Đối chiếu datasheet với hệ kéo sợi và mục đích vải. Khi đổi nguồn xơ, yêu cầu thử kéo sợi hoặc pilot lot vì cùng thông số danh nghĩa có thể cho hành vi khác trên máy.": "Compare the datasheet with the spinning system and fabric end use. When changing fibre sources, request a spinning trial or pilot lot because identical nominal specifications may behave differently on the machine.", "Khi có tranh chấp thành phần, gửi phòng thử nghiệm có năng lực và yêu cầu phương pháp nhận diện phù hợp. Lưu mẫu đối chứng, mã lot và chain of custody.": "When fibre composition is disputed, submit the sample to a competent laboratory and request an appropriate identification method. Retain the reference specimen, lot code and chain-of-custody record.", "Viết yêu cầu mua hàng bằng tính năng đo được: thành phần, cấu trúc, GSM, strength, stretch/recovery, shrinkage, pilling, colorfastness và test method. Duyệt trên vải thật và mẫu may thử.": "Write purchasing requirements in measurable terms: composition, construction, GSM, strength, stretch/recovery, shrinkage, pilling, colourfastness and test method. Approve using actual fabric and a sewn trial sample.", "Lưu lot ID, package number, machine/spindle nếu có, ngày sản xuất và supplier. Giữ mẫu lưu đối chứng và liên kết kết quả lab với cuộn vải thành phẩm.": "Retain the lot ID, package number, machine/spindle where available, production date and supplier. Keep a reference sample and link laboratory results to the finished fabric roll.", "Khi có chênh lệch bất thường, xác minh điều kiện conditioning, calibration, operator, test speed, gauge length và sample preparation trước khi kết luận nhà cung cấp sai.": "When an unusual discrepancy appears, verify conditioning, calibration, operator, test speed, gauge length and sample preparation before concluding that the supplier is at fault.", "Lấy mẫu yarn từ package nghi ngờ, đối chiếu vị trí lỗi trên fabric roll, kiểm tra log máy và dye lot. Không kết luận nguyên nhân chỉ từ ảnh bề mặt.": "Take yarn samples from the suspected package, compare them with defect locations on the fabric roll, and review machine logs and dye lot. Do not determine the cause from a surface photograph alone.", "Đối chiếu từng cột với giới hạn hợp đồng. Kiểm tra report dùng U% hay CVm%, count measured hay nominal, và H hay S3u; không tráo các chỉ số.": "Compare each field with the contractual limit. Check whether the report uses U% or CVm%, measured or nominal count, and H or S3u. Do not interchange these indices.", "Lập NCR/8D ngắn: mô tả lỗi, lot, bằng chứng, phạm vi, containment, nguyên nhân đã xác minh, corrective action, owner và ngày hoàn thành. Không trộn lot lỗi với lot đạt để che biến thiên.": "Prepare a concise NCR/8D record covering the defect, lot, evidence, scope, containment, verified cause, corrective action, owner and due date. Do not mix defective and conforming lots to conceal variation.", "Drying (nếu cần)": "Drying (if required)", "Điểm cần phân biệt:": "Important distinction:", "filament yarn có thể là monofilament hoặc multifilament; sau đó có thể texturize để tạo độ phồng/độ đàn hồi biểu kiến, hoặc ghép/xe nhiều sợi. “Polyester filament” chưa mô tả đủ denier, số filament, tiết diện, luster, twist và trạng thái flat/textured.": "Filament yarn may be monofilament or multifilament. It may then be textured to create bulk/apparent elasticity, or combined/twisted with other yarns. “Polyester filament” does not fully specify denier, filament count, cross-section, lustre, twist or flat/textured status.", "Chú ý khi đọc đơn hàng:": "When Reviewing an Order:", "“30s” hoặc “30 count” không đủ rõ nếu thiếu hệ Ne/Nm và quy ước. Với yarn ply, cần ghi count từng thành phần và cấu trúc ghép/xe; không tự xem count của yarn đơn là count thành phẩm.": "“30s” or “30 count” is ambiguous without the Ne/Nm system and its convention. For ply yarn, state the count of each component and the ply/twist construction; do not assume the single-yarn count is the finished yarn count.", "Nguyên tắc so sánh:": "Comparison Principle:", "Chỉ so sánh kết quả khi cùng phương pháp, thiết bị hoặc cấu hình tương đương, cùng đơn vị, ngưỡng lỗi và điều kiện điều hòa mẫu. Không đặt một ngưỡng chấp nhận chung cho mọi loại sợi; giới hạn phải theo specification và yêu cầu sản phẩm.": "Compare results only when the method, equipment or equivalent configuration, units, fault thresholds and specimen-conditioning conditions are the same. Do not set one universal acceptance limit for all yarn types; limits must follow the specification and product requirements.", "XƠ / FIBER": "FIBRE", "SỢI / YARN": "YARN", "VẢI / FABRIC": "FABRIC", "SẢN PHẨM": "PRODUCT", "Tính chất ở công đoạn trước truyền sang công đoạn sau; xử lý hoàn tất có thể làm thay đổi hành vi cuối cùng.": "Properties at one process stage carry over to the next; finishing treatments can change final performance.", "Staple – xơ hữu hạn": "Staple – finite-length fibre", "Filament – sợi liên tục": "Filament – continuous fibre", "Các đoạn xơ riêng lẻ": "Individual fibre segments", "Một hoặc nhiều filament dài": "One or more continuous filaments", "Cellulose tự nhiên": "Natural cellulose", "Cotton / flax": "Cotton / flax", "Protein tự nhiên": "Natural protein", "Wool / silk": "Wool / silk", "Tổng hợp": "Synthetic", "PET / PA / PP / PAN": "PET / PA / PP / PAN", "Cellulose tái sinh": "Regenerated cellulose", "Viscose / modal / lyocell": "Viscose / modal / lyocell", "Đàn hồi": "Elastic", "Elastane": "Elastane", "Kỹ thuật": "Technical", "Aramid / glass / carbon": "Aramid / glass / carbon", "Tính chất A": "Properties A", "Tính chất B": "Properties B", "Tỷ lệ pha": "Blend ratio", "Tính chất kết hợp": "Combined properties", "Kiểm tra thành phẩm": "Finished-product testing", "Tỷ lệ pha, phân bố xơ và công nghệ kéo sợi quyết định kết quả thực tế": "Blend ratio, fibre distribution and spinning technology determine actual performance", "Chọn phương pháp theo câu hỏi cần xác minh và thành phần dự kiến": "Select the method based on the question to be verified and the expected composition", "Thick / thin places": "Thick / thin places", "Longitudinal streak": "Longitudinal streak", "Count variation": "Count variation", "Hairiness variation": "Hairiness variation", "Direct count": "Direct count", "tex · dtex · denier": "tex · dtex · denier", "Mass / fixed length": "Mass per fixed length", "Indirect count": "Indirect count", "Nm · Ne": "Nm · Ne", "Length / fixed mass": "Length per fixed mass", "Melt": "Melt", "Spinneret": "Spinneret", "Quench": "Quench", "Solidify": "Solidify", "Drawing": "Drawing", "Orient": "Orient", "Winding": "Winding", "Sliver / roving": "Sliver / roving", "Feed": "Feed", "Drafting": "Drafting", "Attenuation": "Attenuation", "Twisting": "Twisting", "Spindle / traveller": "Spindle / traveller", "S twist": "S twist", "Z twist": "Z twist", "Spun yarn": "Spun yarn", "Flat filament yarn": "Flat filament yarn", "Textured filament": "Textured filament", "Lot / tỷ lệ": "Lot / blend ratio", "Sơ đồ chuỗi xơ, sợi, vải và sản phẩm": "Diagram of the fibre-to-yarn-to-fabric-to-product sequence", "So sánh xơ staple có chiều dài hữu hạn và filament liên tục": "Comparison of finite-length staple fibres and continuous filaments", "Phân nhóm xơ dệt theo nguồn gốc và nhóm vật liệu": "Classification of textile fibres by origin and material group", "Sơ đồ phối trộn hai nhóm xơ thành blend yarn và kiểm tra": "Diagram of blending two fibre groups into blend yarn and testing", "Bốn nhóm tính chất xơ cần xem trên datasheet": "Four groups of fibre properties to review in a datasheet", "Quy trình nhận diện xơ từ truy xuất nguồn gốc đến báo cáo phân tích": "Fibre identification process from traceability to analytical report", "Các dạng biến thiên sợi có thể tạo lỗi ngoại quan trên vải": "Yarn variations that can create visible fabric defects", "So sánh hệ chi số trực tiếp và gián tiếp của sợi": "Comparison of direct and indirect yarn count systems", "Chuỗi công đoạn melt spinning tạo filament": "Melt-spinning sequence for filament production", "Sơ đồ ring spinning từ cấp sợi thô qua kéo mảnh, tạo xoắn đến cuốn ống": "Ring-spinning flow from roving feed through drafting and twisting to winding", "Minh họa hướng xoắn S và Z của sợi": "Illustration of S and Z yarn twist directions", "So sánh dạng sợi spun, filament phẳng và filament texturized": "Comparison of spun yarn, flat filament and textured filament"};
  var pageTitle = { vi: "Garment Academy | Xơ và sợi", en: "Garment Academy | Fibres and Yarns" };
  var dictionary = Object.create(null);
  var pageDescription = { vi: "Chuyên đề xơ và sợi dệt may: cotton, polyester, viscose, nylon, elastane, staple, filament, yarn count, twist, evenness và kiểm soát chất lượng.", en: "A textile fibre and yarn guide covering cotton, polyester, viscose, nylon, elastane, staple and filament fibres, yarn count, twist, evenness and quality control." };
  var index = 0;

  function makeKey(kind) {
    index += 1;
    return 'phase4.' + kind + '.' + index;
  }
  function translatedValue(source) {
    var leading = (source.match(/^\s*/) || [''])[0];
    var trailing = (source.match(/\s*$/) || [''])[0];
    var trimmed = source.replace(/\s+/g, ' ').trim();
    if (!Object.prototype.hasOwnProperty.call(translations, trimmed)) return null;
    return { leading: leading, trailing: trailing, value: translations[trimmed] };
  }
  function annotateText() {
    var walker = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT);
    var nodes = [];
    var node;
    while ((node = walker.nextNode())) nodes.push(node);
    nodes.forEach(function (textNode) {
      var parent = textNode.parentElement;
      if (!parent || /^(SCRIPT|STYLE|NOSCRIPT|TEMPLATE)$/.test(parent.tagName)) return;
      if (parent.closest && parent.closest('[data-i18n]')) return;
      var source = textNode.nodeValue;
      var result = translatedValue(source);
      if (!result) return;
      var key = makeKey('text');
      dictionary[key] = result.leading + result.value + result.trailing;
      if (parent.namespaceURI === 'http://www.w3.org/2000/svg') {
        var tag = parent.tagName.toLowerCase();
        if ((tag === 'text' || tag === 'tspan' || tag === 'title') && parent.childNodes.length === 1) {
          parent.setAttribute('data-i18n', key);
        } else {
          var tspan = document.createElementNS('http://www.w3.org/2000/svg', 'tspan');
          tspan.setAttribute('data-i18n', key);
          tspan.textContent = source;
          parent.replaceChild(tspan, textNode);
        }
      } else {
        var span = document.createElement('span');
        span.setAttribute('data-i18n', key);
        span.textContent = source;
        parent.replaceChild(span, textNode);
      }
    });
  }
  function annotateAttributes() {
    var attrs = ['title', 'placeholder', 'aria-label', 'alt'];
    document.body.querySelectorAll('*').forEach(function (el) {
      attrs.forEach(function (attr) {
        var source = el.getAttribute(attr);
        if (!source) return;
        var result = translatedValue(source);
        if (!result) return;
        var key = makeKey('attr');
        dictionary[key] = result.value;
        if (attr === 'alt') {
          el.setAttribute('data-i18n-alt', key);
          el.setAttribute('data-i18n-source-alt', source);
        } else {
          el.setAttribute('data-i18n-' + attr, key);
        }
      });
    });
  }
  function updateAltAndTitle() {
    var lang = window.AppNhoI18n ? window.AppNhoI18n.getLanguage() : 'vi';
    document.title = pageTitle[lang] || pageTitle.vi;
    var description = document.querySelector('meta[name="description"]');
    if (description) description.setAttribute('content', pageDescription[lang] || pageDescription.vi);
    document.body.querySelectorAll('[data-i18n-alt]').forEach(function (el) {
      var key = el.getAttribute('data-i18n-alt');
      if (lang === 'en' && Object.prototype.hasOwnProperty.call(dictionary, key)) {
        el.setAttribute('alt', dictionary[key]);
      } else {
        el.setAttribute('alt', el.getAttribute('data-i18n-source-alt') || '');
      }
    });
  }

  annotateText();
  annotateAttributes();
  if (window.AppNhoI18n) {
    window.AppNhoI18n.register('en', dictionary);
    window.AppNhoI18n.setPageReady(true);
  }
  updateAltAndTitle();
  window.addEventListener('appnho:languagechange', updateAltAndTitle);
  document.addEventListener('DOMContentLoaded', updateAltAndTitle, { once: true });
})();